import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Button,
  CircularProgress,
  Alert,
  useTheme,
  useMediaQuery,
  Modal,
  IconButton,
} from '@mui/material';
import { Refresh, Close, PictureAsPdf, ZoomIn } from '@mui/icons-material';

const Awards = () => {
  const [awardsData, setAwardsData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [imageLoadingStates, setImageLoadingStates] = useState({});
  const [selectedPdf, setSelectedPdf] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const isTablet = useMediaQuery(theme.breakpoints.down('md'));

  const SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbw8f0wiemrCnF9ctv7A_H_eDEH8RuR6jFSsOK3kgoxc0MIorROzhsjRjZ9zaHnvw0tXMg/exec';

const fetchAwardsData = async () => {
  setLoading(true);
  setError(null);
  try {
    console.log('Fetching awards data...');
    const response = await fetch(`${SCRIPT_URL}?type=awards&t=${Date.now()}`);
    
    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }
    
    const text = await response.text();
    console.log('Raw response:', text);
    
    let result;
    try {
      result = JSON.parse(text);
    } catch (parseError) {
      throw new Error('Invalid JSON response from server');
    }
    
    console.log('Awards API Response:', result);
    
    if (result.success && result.data) {
      const transformedData = result.data.map((item, index) => ({
        awardNo: item.awardNo ?? index + 1,
        fileName: item.fileName || `Certificate ${item.awardNo ?? index + 1}`,
        pdfUrl: item.pdfUrl,
        thumbnailUrl: item.thumbnailUrl,
        fileId: item.fileId
      }));
      
      console.log('Transformed awards data:', transformedData);
      setAwardsData(transformedData);
      
      const initialLoadingStates = {};
      transformedData.forEach((item, index) => {
        initialLoadingStates[index] = true;
      });
      setImageLoadingStates(initialLoadingStates);
    } else {
      throw new Error(result.error || 'No data received from server');
    }
  } catch (err) {
    console.error('Awards fetch error:', err);
    setError(`Error loading certificates: ${err.message}`);
  } finally {
    setLoading(false);
  }
};

  const handleImageLoad = (index) => {
    setImageLoadingStates(prev => ({
      ...prev,
      [index]: false
    }));
  };

  const handleImageError = (index, url) => {
    console.error(`Failed to load thumbnail ${index}:`, url);
    setImageLoadingStates(prev => ({
      ...prev,
      [index]: false
    }));
  };

  const openPdfModal = (award) => {
    setSelectedPdf(award);
    setIsModalOpen(true);
    document.body.style.overflow = 'hidden';
  };

  const closePdfModal = () => {
    setIsModalOpen(false);
    setSelectedPdf(null);
    document.body.style.overflow = 'unset';
  };

  const downloadPdf = (award) => {
    const downloadUrl = `https://drive.google.com/uc?export=download&id=${award.fileId}`;
    window.open(downloadUrl, '_blank');
  };

  // Determine columns based on screen size
  const getColumns = () => {
    if (isMobile) return 2;
    if (isTablet) return 3;
    return 4;
  };

  useEffect(() => {
    fetchAwardsData();
  }, []);

  if (loading) {
    return (
      <Box 
        display="flex" 
        justifyContent="center" 
        alignItems="center" 
        minHeight="200px"
        flexDirection="column"
        gap={2}
      >
        <CircularProgress />
        <Typography variant="body1">Loading certificates...</Typography>
      </Box>
    );
  }

  if (error) {
    return (
      <Box p={3} display="flex" flexDirection="column" alignItems="center" gap={2}>
        <Alert severity="error" sx={{ width: '100%', maxWidth: 400 }}>
          {error}
        </Alert>
        <Button 
          variant="contained" 
          startIcon={<Refresh />}
          onClick={fetchAwardsData}
        >
          Try Again
        </Button>
      </Box>
    );
  }

  return (
    <Box sx={{ p: { xs: 1, sm: 2, md: 3 }, maxWidth: 1200, margin: '0 auto' }}>
      <Typography 
        variant="h3" 
        component="h1" 
        align="center" 
        gutterBottom
        sx={{ 
          fontSize: { xs: '1.75rem', sm: '2.5rem', md: '3rem' },
          mb: 1 
        }}
      >
        Awards & Certificates
      </Typography>
      
      <Typography 
        variant="h6" 
        component="p" 
        align="center" 
        color="text.secondary"
        sx={{ mb: 3 }}
      >
        {awardsData.length} {awardsData.length === 1 ? 'certificate' : 'certificates'}
      </Typography>

      {awardsData.length === 0 ? (
        <Box textAlign="center" p={3}>
          <Typography variant="body1" color="text.secondary" gutterBottom>
            No certificates found.
          </Typography>
          <Button 
            variant="outlined" 
            startIcon={<Refresh />}
            onClick={fetchAwardsData}
            sx={{ mt: 2 }}
          >
            Refresh
          </Button>
        </Box>
      ) : (
        <Box
          sx={{
            columnCount: getColumns(),
            columnGap: 2,
            '& > *': {
              breakInside: 'avoid',
              marginBottom: 2,
              display: 'inline-block',
              width: '100%',
            }
          }}
        >
          {awardsData.map((award, idx) => (
            <Box
              key={idx}
              sx={{
                borderRadius: 2,
                overflow: 'hidden',
                boxShadow: 1,
                transition: 'all 0.3s ease',
                backgroundColor: 'background.paper',
                '&:hover': {
                  transform: 'translateY(-4px)',
                  boxShadow: 4,
                },
                position: 'relative',
                display: 'inline-block',
                width: '100%',
              }}
            >
              {/* Loader */}
              {imageLoadingStates[idx] && (
                <Box
                  sx={{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    right: 0,
                    bottom: 0,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    backgroundColor: 'rgba(0,0,0,0.05)',
                    zIndex: 1,
                    minHeight: 200,
                  }}
                >
                  <CircularProgress size={40} />
                </Box>
              )}
              
              {/* PDF Thumbnail */}
              <Box
                component="img"
                src={award.thumbnailUrl}
                alt={award.fileName}
                loading="lazy"
                sx={{
                  width: '100%',
                  height: 'auto',
                  display: 'block',
                  opacity: imageLoadingStates[idx] ? 0 : 1,
                  transition: 'opacity 0.3s ease',
                  cursor: 'pointer',
                }}
                onLoad={() => handleImageLoad(idx)}
                onError={() => handleImageError(idx, award.thumbnailUrl)}
                onClick={() => openPdfModal(award)}
              />
              
              {/* Overlay with actions */}
              <Box
                sx={{
                  position: 'absolute',
                  bottom: 0,
                  left: 0,
                  right: 0,
                  background: 'linear-gradient(transparent, rgba(0,0,0,0.7))',
                  color: 'white',
                  p: 2,
                  opacity: 0,
                  transition: 'opacity 0.3s ease',
                  '&:hover': {
                    opacity: 1,
                  },
                }}
              >
                <Typography variant="body2" noWrap title={award.fileName}>
                  {award.fileName}
                </Typography>
                <Box sx={{ display: 'flex', gap: 1, mt: 1 }}>
                  <IconButton
                    size="small"
                    sx={{ color: 'white', backgroundColor: 'rgba(255,255,255,0.2)' }}
                    onClick={(e) => {
                      e.stopPropagation();
                      openPdfModal(award);
                    }}
                    title="View PDF"
                  >
                    <ZoomIn fontSize="small" />
                  </IconButton>
                  <IconButton
                    size="small"
                    sx={{ color: 'white', backgroundColor: 'rgba(255,255,255,0.2)' }}
                    onClick={(e) => {
                      e.stopPropagation();
                      downloadPdf(award);
                    }}
                    title="Download PDF"
                  >
                    <PictureAsPdf fontSize="small" />
                  </IconButton>
                </Box>
              </Box>
            </Box>
          ))}
        </Box>
      )}

      {/* PDF Viewer Modal */}
      <Modal
        open={isModalOpen}
        onClose={closePdfModal}
        sx={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          p: 2,
        }}
      >
        <Box
          sx={{
            position: 'relative',
            width: '90vw',
            height: '90vh',
            backgroundColor: 'background.paper',
            borderRadius: 2,
            overflow: 'hidden',
            boxShadow: 24,
            outline: 'none',
          }}
        >
          <IconButton
            onClick={closePdfModal}
            sx={{
              position: 'absolute',
              top: 8,
              right: 8,
              backgroundColor: 'rgba(255,255,255,0.9)',
              '&:hover': {
                backgroundColor: 'rgba(255,255,255,1)',
              },
              zIndex: 1,
            }}
          >
            <Close />
          </IconButton>
          
          <Box sx={{ height: '100%', p: 1 }}>
            <Typography variant="h6" sx={{ p: 2, pb: 1 }}>
              {selectedPdf?.fileName}
            </Typography>
            
            <Box sx={{ height: 'calc(100% - 80px)' }}>
              <iframe
                src={`https://drive.google.com/file/d/${selectedPdf?.fileId}/preview`}
                width="100%"
                height="100%"
                style={{ border: 'none', borderRadius: 8 }}
                title={selectedPdf?.fileName}
              />
            </Box>
            
            <Box sx={{ p: 2, display: 'flex', gap: 1, justifyContent: 'center' }}>
              <Button
                variant="contained"
                startIcon={<PictureAsPdf />}
                onClick={() => selectedPdf && downloadPdf(selectedPdf)}
              >
                Download PDF
              </Button>
              <Button
                variant="outlined"
                onClick={closePdfModal}
              >
                Close
              </Button>
            </Box>
          </Box>
        </Box>
      </Modal>
    </Box>
  );
};

export default Awards;
